-- Patient Safety & Quality Improvement: Part 2 (Questions 51-100)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- INVESTIGATING ERRORS (RCA & FMEA)
    (v_topic_id, 'Which of the following processes is MANDATED by the Joint Commission (TJC) following a sentinel event?', '["Failure Mode and Effects Analysis (FMEA)", "Root Cause Analysis (RCA)", "A formal public apology", "The immediate termination of the involved staff"]', 1, 'The Joint Commission requires hospitals to perform a Root Cause Analysis (RCA) following a sentinel event to identify systems-level improvements.'),
    (v_topic_id, 'Root Cause Analysis (RCA) is best described as a process that is:', '["Prospective and individual-focused", "Retrospective and systems-focused", "Prospective and systems-focused", "Retrospective and punitive"]', 1, 'RCA is a retrospective (after-the-fact) process that focuses on identifying system-level failures rather than individual blame.'),
    (v_topic_id, 'A "Fishbone Diagram" (also known as an Ishikawa diagram) is used during an RCA to:', '["Identify the financial cost of an error", "Categorize potential causes of a problem into groups like Equipment, People, and Process", "Track the patient''s clinical recovery", "Graph the frequency of errors over time"]', 1, 'The Fishbone diagram is a visualization tool used in RCA to organize potential causes of an error into logical categories.'),
    (v_topic_id, 'Failure Mode and Effects Analysis (FMEA) differs from RCA in that FMEA is:', '["Performed after a patient dies", "A prospective process used to identify potential failures before they occur", "A method for determining legal liability", "Focused only on surgical errors"]', 1, 'FMEA is a proactive (prospective) tool used to identify and mitigate risks in a process BEFORE they result in patient harm.'),
    (v_topic_id, 'In an FMEA, a "Risk Priority Number" (RPN) is calculated by multiplying which three factors?', '["Cost, Complexity, and Time", "Severity, Probability, and Detectability", "Age, Comorbidity, and Urgency", "Volume, Variance, and Value"]', 1, 'The RPN helps prioritize which failure modes to address first by considering how severe the harm would be, how likely it is to happen, and how easily it would be detected before reaching the patient.'),

    -- RCA STEPS & TECHNIQUES
    (v_topic_id, 'The "Five Whys" technique is intended to help an RCA team:', '["Find five different people to blame", "Peel away layers of symptoms to find the true underlying cause of a problem", "Spend at least five hours on every investigation", "Interview five different witnesses"]', 1, 'By repeatedly asking "Why?" (typically five times), investigators can move past superficial explanations to reach the root system failure.'),
    (v_topic_id, 'Which of the following is an essential characteristic of an effective RCA team?', '["It should be composed entirely of hospital lawyers", "It should be multi-disciplinary and include those close to the process being studied", "It should be led by the CEO alone", "It should exclude anyone who was involved in the error"]', 1, 'A multi-disciplinary approach (including nurses, physicians, pharmacists, etc.) ensures that all perspectives of the system are considered.'),
    (v_topic_id, 'The final and most important step of an RCA is:', '["Writing a report for the files", "Identifying the root cause", "Implementing and monitoring a sustainable action plan to prevent recurrence", "Filing an insurance claim"]', 2, 'An RCA is only successful if it leads to meaningful system changes that are monitored for effectiveness over time.'),
    (v_topic_id, 'If an RCA team identifies that a nurse''s fatigue contributed to a medication error, the most effective "Action Plan" would be:', '["Firing the nurse", "Mandating a 10-hour rest period between shifts and implementing automated medication dispensing", "Giving the nurse a warning letter", "Telling everyone to drink more coffee"]', 1, 'Effective actions focus on system redesign (standardized rest periods, automation) rather than individual discipline.'),
    (v_topic_id, 'Which of the following is a "Proximate Cause" rather than a "Root Cause"?', '["A physician misreading a handwritten order", "Poor lighting in the medication room", "Lack of a computerized physician order entry (CPOE) system", "A culture that discourages questioning authority"]', 0, 'A proximate cause is the event that happened just before the error (the active failure). The root cause is the underlying system flaw (poor lighting, lack of CPOE, etc.) that allowed it to happen.'),

    -- JUST CULTURE & ACCOUNTABILITY
    (v_topic_id, 'In a "Just Culture," human error is managed primarily through:', '["Disciplinary action", "System redesign and support for the individual", "Fines", "Public disclosure of the person''s name"]', 1, 'Human error (unintentional slips or lapses) is seen as a system failure requiring system improvement and support for the person involved.'),
    (v_topic_id, 'Which behavior in a Just Culture warrants a disciplinary or punitive response?', '["A \"slip\" while performing a complex task", "Reckless behavior (conscious disregard of a substantial and unjustifiable risk)", "Reporting a near miss", "Forgetting a step in a rare procedure"]', 1, 'Just Culture holds individuals accountable for reckless behavior while protecting those who make honest human errors.'),
    (v_topic_id, '"At-risk behavior" (e.g., taking a shortcut because it seems safe and saves time) is best managed in a Just Culture by:', '["Ignoring it", "Firing the person immediately", "Coaching the individual and addressing the system incentives that encouraged the shortcut", "Suspending their medical license"]', 2, 'At-risk behaviors often occur because the system makes the "wrong way" easier. Management involves coaching the person and removing the system-level drivers for the shortcut.'),
    (v_topic_id, 'The "Second Victim" phenomenon refers to:', '["The patient''s family members", "The healthcare provider who is traumatized by their involvement in a serious medical error", "The insurance company", "The hospital administrator"]', 1, 'Providers often experience significant guilt, anxiety, and depression after an error; a safe system provides support for these "second victims."'),
    (v_topic_id, 'Which of the following is the most significant barrier to a "Culture of Safety"?', '["Lack of funding", "A hierarchical culture that punishes error and discourages speaking up", "Old medical equipment", "A high volume of patients"]', 1, 'A "Culture of Blame" prevents the reporting and analysis necessary to improve safety.'),

    -- DISCLOSURE OF ERRORS
    (v_topic_id, 'When a serious medical error occurs, professional ethics and many state laws require:', '["Immediate and full disclosure to the patient/family", "Waiting for the patient to ask what happened", "Denying that an error occurred to avoid a lawsuit", "Waiting until the legal team gives permission"]', 0, 'Honesty and transparency are ethical imperatives. Disclosure should be prompt, factual, and include an apology.'),
    (v_topic_id, 'A "Full Disclosure" after a medical error should ideally include:', '["A factual description of what happened", "An apology and expression of regret", "A plan for investigation and steps to prevent recurrence", "All of the above"]', 3, 'Comprehensive disclosure includes facts, apology, and a commitment to future safety.'),
    (v_topic_id, 'What is an "Apology Law" in the context of medical error?', '["A law that makes an apology mandatory", "A law that prevents an apology from being used as an admission of guilt in court", "A law that fines doctors who don''t apologize", "A law that requires patients to apologize to doctors"]', 1, 'Apology laws are designed to encourage transparency by protecting expressions of regret from being used against the provider in malpractice litigation.'),
    (v_topic_id, 'True or False: Studies show that full and honest disclosure after an error typically increases the likelihood and cost of lawsuits.', '["True", "False"]', 1, 'Evidence suggests that transparency and a fair compensation process (Disclosure, Apology, and Offer programs) can actually decrease litigation and costs.'),
    (v_topic_id, 'If a "No-Harm Event" occurs (an error reached the patient but caused no harm), should it be disclosed?', '["No, because the patient wasn''t hurt", "Yes, most ethical guidelines recommend disclosure if the error reached the patient", "Only if the patient noticed the error", "Only if the error was \"major\""]', 1, 'Patients have a right to know what happened in their care if an error reached them, even if no harm resulted.'),

    -- REPORTING SYSTEMS
    (v_topic_id, 'The primary purpose of an internal incident reporting system is to:', '["Gather evidence for the legal department", "Identify patterns and system weaknesses for quality improvement", "Rank the performance of individual nurses", "Increase hospital billing"]', 1, 'Reporting is a "sensor" for the system, allowing the organization to learn from near misses and errors.'),
    (v_topic_id, 'Why are "Near Misses" considered high-value data for reporting systems?', '["They happen more frequently than actual errors", "They provide a \"free lesson\" in system failure without patient harm", "They are easier to investigate", "All of the above"]', 3, 'Near misses reveal the same system flaws as adverse events but without the cost of human injury.'),
    (v_topic_id, 'Which type of reporting system is most effective at capturing safety data?', '["A mandatory system with harsh penalties for non-reporting", "A voluntary, confidential, and non-punitive system", "A system where reports are public", "A system only accessible by the hospital CEO"]', 1, 'People are much more likely to report if they feel safe and see that the data is used for improvement rather than punishment.'),
    (v_topic_id, 'An "Anonymous" reporting system differs from a "Confidential" one in that:', '["Anonymous means the reporter''s identity is never known", "Confidential means the identity is known but protected", "Both A and B", "Neither"]', 2, 'In confidential systems, investigators can follow up with the reporter for more details, which is often more useful for RCA.'),
    (v_topic_id, 'External reporting of sentinel events to The Joint Commission is:', '["Always mandatory", "Voluntary (but highly encouraged and often required by state law)", "Illegal", "Required only for pediatric cases"]', 1, 'While TJC reporting is technically voluntary in some contexts, it is a standard expectation and often linked to state licensing requirements.'),

    -- QUALITY METRICS & TRANSPARENCY
    (v_topic_id, 'Public reporting of hospital quality metrics (e.g., Hospital Compare) is intended to:', '["Confuse patients", "Drive quality improvement through competition and transparency", "Identify the cheapest hospitals", "Promote hospital advertising"]', 1, 'Transparency encourages hospitals to benchmark themselves against peers and improve their performance.'),
    (v_topic_id, '"Benchmarking" in healthcare refers to:', '["Setting a chair in the hallway", "Comparing an organization''s performance against best-in-class peers or national standards", "Calculating the average weight of patients", "Standardizing the height of exam tables"]', 1, 'Benchmarking helps organizations identify where they are lagging behind and sets targets for improvement.'),
    (v_topic_id, 'Which of the following is a "Patient-Centered" quality metric?', '["The number of MRIs performed", "Patient satisfaction survey scores (HCAHPS)", "The hospital''s net profit margin", "The number of physicians on staff"]', 1, 'HCAHPS (Hospital Consumer Assessment of Healthcare Providers and Systems) measures the patient''s perspective of their care.'),
    (v_topic_id, 'A "Value-Based Purchasing" model links hospital reimbursement to:', '["The total volume of patients seen", "The number of procedures performed", "Performance on quality and safety metrics", "The hospital''s geographic location"]', 2, 'VBP shifts payment from "volume" to "value," rewarding high-quality, safe care.'),
    (v_topic_id, 'A "Dashboard" in a clinical unit is used to:', '["Watch television", "Display real-time performance on key quality and safety metrics to front-line staff", "Control the lighting in the unit", "Hide error data from patients"]', 1, 'Dashboards make data visible and actionable for the team doing the work.'),

    -- PROFESSIONALISM & ACCOUNTABILITY
    (v_topic_id, 'If a physician witnesses a colleague performing a procedure while visibly intoxicated, their first professional obligation is to:', '["Ignore it to protect their colleague", "Ensure the safety of the current patient (e.g., stop the procedure)", "Wait until the next day to talk to them", "Write a letter to the medical board"]', 1, 'Patient safety is the absolute priority and supersedes professional courtesy.'),
    (v_topic_id, 'Medical boards primarily exist to:', '["Protect the interests of physicians", "Protect the safety of the public", "Collect membership dues", "Organize medical conferences"]', 1, 'The primary mission of medical boards is public protection through licensing and regulation.'),
    (v_topic_id, 'Which of the following is an example of "Disruptive Behavior" that threatens patient safety?', '["Asking for a second opinion", "Yelling at a nurse for calling with a question", "Following a checklist", "Reporting a near miss"]', 1, 'Intimidating or disruptive behavior inhibits communication and makes others afraid to speak up about safety concerns.'),
    (v_topic_id, 'The "Pact" of professional accountability means that clinicians agree to:', '["Never make a mistake", "Be accountable for following safe practices and speaking up about risks", "Always work alone", "Blame the system for every personal failing"]', 1, 'Professionalism includes a commitment to following standards and contributing to a safe environment.'),
    (v_topic_id, '"Social Loafing" in a medical team occurs when:', '["Individuals work harder in a group", "Individuals exert less effort because they feel others will catch the errors", "The team takes a long lunch break", "The team is too large"]', 1, 'This is a risk in redundant systems where staff assume "someone else checked it."'),

    -- MORE INVESTIGATION TECHNIQUES
    (v_topic_id, 'A "Pareto Chart" is used in quality improvement to:', '["Identify which few causes are responsible for the majority of problems (80/20 rule)", "Show the clinical progress of a patient", "List the names of all hospital staff", "Graph the hospital''s stock price"]', 0, 'The Pareto Principle helps teams focus their limited resources on the "vital few" problems that have the biggest impact.'),
    (v_topic_id, 'A "Run Chart" is used to:', '["Find out who is the fastest runner in the hospital", "Track a metric over time to identify trends or shifts", "List the medications a patient is taking", "Organize the surgical schedule"]', 1, 'Run charts (or control charts) are essential for determining if a change resulted in a sustained improvement.'),
    (v_topic_id, 'In a "Fishbone Diagram," the "head" of the fish represents:', '["The hospital CEO", "The problem or \"Effect\" being studied", "The most likely solution", "The date of the error"]', 1, 'The "bones" are the causes, and the "head" is the specific outcome or problem the team wants to understand.'),
    (v_topic_id, 'Which of the following is a "Human Factors" reason why RCAs often fail to prevent recurrence?', '["The team is too small", "The \"action plans\" focus on low-leverage interventions like \"retraining\" or \"reminders\"", "The investigation takes too long", "The cost is too high"]', 1, 'Strong action plans focus on system redesign (forcing functions, automation), not just telling people to "be more careful."'),
    (v_topic_id, 'The "Huddles" used in high-reliability organizations are designed to improve:', '["Financial transparency", "Situational awareness", "The hospital''s social media presence", "Staff parking"]', 1, 'Huddles help the team anticipate risks and coordinate their response to a changing environment.'),

    -- MISC QUALITY & SAFETY
    (v_topic_id, 'Which organization is responsible for the "National Patient Safety Goals"?', '["American Medical Association (AMA)", "The Joint Commission (TJC)", "Center for Disease Control (CDC)", "Department of Justice"]', 1, 'TJC updates these goals annually to focus hospital attention on the most critical safety issues (e.g., patient ID, alarm safety).'),
    (v_topic_id, 'The "Check-Back" technique in communication involves:', '["The sender verifying that the message was received and understood correctly", "Checking the patient''s back for pressure ulcers", "Looking back at old medical records", "Calling the patient after discharge"]', 0, 'Check-back is the "loop" in closed-loop communication.'),
    (v_topic_id, 'What is "Work-Around" in the context of patient safety?', '["A more efficient way to work", "A non-standard process used to bypass a perceived system barrier (e.g., overriding a barcode scanner)", "A type of physical therapy", "A collaborative meeting"]', 1, 'Work-arounds are common in flawed systems but often create new safety risks.'),
    (v_topic_id, 'Which of the following is the most important factor in sustaining quality improvements?', '["Buying new software every year", "Engaging front-line staff in the design and ownership of the change", "Hiring more managers", "Increasing the number of audits"]', 1, 'Changes are most sustainable when those who do the work are involved in creating the solution.'),
    (v_topic_id, 'The "PDSA" cycle is most closely associated with:', '["Investigating an error", "Testing a small-scale change for improvement", "Firing an employee", "Building a new hospital"]', 1, 'Plan-Do-Study-Act is the engine of rapid-cycle quality improvement.'),

    -- ERROR TYPES REVISITED
    (v_topic_id, 'A "Never Event" is usually __________ for the hospital to bill for.', '["Mandatory", "Prohibited (most payers will not reimburse for care related to Never Events)", "Optional", "Highly profitable"]', 1, 'CMS and many private insurers refuse to pay for the additional costs associated with specific Never Events (like objects left in surgery).'),
    (v_topic_id, 'If a patient falls and breaks a hip due to a lack of bed rails, this is:', '["A natural event", "An adverse event caused by a latent system error", "A near miss", "Malpractice only if the nurse is sued"]', 1, 'The omission of safety equipment (bed rails) led to patient harm.'),
    (v_topic_id, 'The "Standard of Care" is best defined as:', '["The highest possible level of care achievable", "What a reasonable, prudent clinician would do in similar circumstances", "The most expensive care available", "What the hospital CEO says it is"]', 1, 'Standard of care is the legal and professional baseline for acceptable practice.'),
    (v_topic_id, 'Which of the following is a "System Failure"?', '["A fatigued resident making a typo", "An EHR that allows 100x overdoses without an alert", "A nurse forgetting to wash their hands", "A surgeon being distracted by music"]', 1, 'While the others are active failures, the lack of an alert is a flaw in the system design.'),
    (v_topic_id, 'What is the "First Victim" in a medical error?', '["The nurse", "The patient", "The doctor", "The hospital"]', 1, 'The patient who suffers harm is the first victim. The provider involved is the second victim.')
END $$;
